(function(r){'use strict';r.YouthPerformanceUI=class{
 constructor({get,change,stop}){this.dialog=document.querySelector('#graphics');this.get=get;this.change=change;this.stop=stop;this.dialog.addEventListener('change',()=>{change({fps:Number(document.querySelector('#graphicsFps').value),reduced:document.querySelector('#graphicsReduced').checked,camera:document.querySelector('#graphicsCamera').checked,monitor:document.querySelector('#graphicsMonitor').checked});});document.querySelector('#closeGraphics').onclick=()=>this.dialog.close();document.querySelector('#openGraphics').onclick=()=>this.open();this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.dialog.close();});}
 open(){this.stop();const s=this.get();document.querySelector('#graphicsFps').value=String(s.fps);document.querySelector('#graphicsReduced').checked=s.reduced;document.querySelector('#graphicsCamera').checked=s.camera;document.querySelector('#graphicsMonitor').checked=s.monitor;this.dialog.showModal();}
 update(m,online,motion){const el=document.querySelector('#performanceMonitor');el.hidden=!this.get().monitor;if(el.hidden)return;el.textContent=`${m.fps.toFixed(1)} FPS rendered | ${m.frameMs.toFixed(2)} ms/frame | variation ${m.variationMs.toFixed(2)} ms\nRAF ${m.rafHz.toFixed(1)} Hz | ${online?'server snapshots '+m.snapshotHz.toFixed(1):'simulation '+m.simulationHz.toFixed(1)} Hz\n${online?'RTT '+(m.rtt===null?'measuring':m.rtt.toFixed(0)+' ms')+' | host simulation '+(m.serverHz===null?'measuring':m.serverHz.toFixed(1)+' Hz'):'Solo simulation 60 Hz'} | target ${this.get().fps||'Auto'}`;if(motion)el.textContent+=`\n${motion.name} | ${motion.speed.toFixed(2)} m/s | ${motion.cadence.toFixed(2)} steps/s\nStride ${motion.stride.toFixed(2)} m | phase ${motion.phase.toFixed(3)} | travelled ${motion.distance.toFixed(2)} m`;}
 };})(typeof globalThis!=='undefined'?globalThis:this);
